// Auto-generated embedded icons for Krix MCP Gateway
// Embedded directly as Base64 Data URIs (identical to github-mcp-server pattern).
// This guarantees zero network or disk dependency when Gemini performs the handshake.

export interface McpIcon {
  src: string;
  mimeType: string;
  theme?: "light" | "dark";
}

export const ICON_48_DATA_URI = "data:image/png;base64,";
export const ICON_24_DATA_URI = "data:image/png;base64,";

// Canonical 2-theme array matching GitHub MCP Server (pkg/octicons/octicons.go)
// Sizes field is omitted intentionally for 100% compatibility across all MCP client versions.
export const SERVER_ICONS: McpIcon[] = [
  {
    src: ICON_48_DATA_URI,
    mimeType: "image/png",
    theme: "light"
  },
  {
    src: ICON_48_DATA_URI,
    mimeType: "image/png",
    theme: "dark"
  }
];

export const ICON_48_BUFFER = Buffer.from(ICON_48_DATA_URI.split(',')[1], 'base64');
export const ICON_24_BUFFER = Buffer.from(ICON_24_DATA_URI.split(',')[1], 'base64');
